var pontoonResult=function(){var n={h:0,d:1,c:2,s:3};return{onInputNickname:function(n){n.preventDefault();n.currentTarget.value!==""&&$(".error").addClass("hidden")},reset:function(n){n.preventDefault();location.reload()},submit:function(n){var i,u,r,t,f,e;if(n.preventDefault(),$("#success").hide(),$("#fail").hide(),$("#spinner").show(),i=$("#nickname").val(),i===""){$(".error").removeClass("hidden");$("#spinner").hide();return}for(u=$("#dealer").val(),r=[],t=1;t<=6;t++)f=$("#hand"+t).val(),r.push(f);e={name:i,dealer:this.transformDealer(u),hands:this.transformHands(r)};$.ajax({type:"POST",url:"SetPontoonResult",data:e,dataType:"html"}).done(function(n){$("#spinner").hide();n==="true"?$("#success").show():$("#fail").show()})},transformDealer:function(n){const i=n.split(","),t=[];return $.each(i,(n,i)=>{t.push(this.parseCard(i))}),t},transformHands:function(n){const t=[];return $.each(n,(n,i)=>{if(i!==""){const r=i.split(","),u=r.map(n=>this.parseCard(n));t.push({pos:n+1,cards:u})}n++}),t},parseCard:function(t){const i=t.split("-"),r=i[0],u=i[1];return{rank:r,suit:n[u]}}}}();